-- name: ListNotificationChannelsOfTeam :many
SELECT * FROM notification_channels WHERE team_id = sqlc.arg('team_id') ORDER BY name, id;

-- name: NotificationChannelInTeam :one
SELECT * FROM notification_channels WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id');

-- name: NotificationChannelsByIDsInTeam :many
-- Team scope: the channels a monitor routes to, in no particular order (the caller reorders).
-- ids is a comma-joined list (never empty: string_to_array('', ',') would otherwise match nothing
-- and also nothing weird — but empty is never passed).
SELECT * FROM notification_channels WHERE team_id = sqlc.arg('team_id') AND id = ANY(string_to_array(sqlc.arg('ids')::text, ','));

-- name: InsertNotificationChannel :one
-- id is minted by the caller (like internal/deploy's newUUID) so the channel's url/secret can be
-- sealed bound to its own id before the row exists.
INSERT INTO notification_channels (id, team_id, kind, name, emails, url_sealed, secret_sealed, events, enabled, created_by)
VALUES (sqlc.arg('id'), sqlc.arg('team_id'), sqlc.arg('kind'), sqlc.arg('name'), sqlc.arg('emails'), sqlc.arg('url_sealed'), sqlc.arg('secret_sealed'),
    sqlc.arg('events'), sqlc.arg('enabled'), sqlc.arg('created_by'))
RETURNING *;

-- name: UpdateNotificationChannelInTeam :one
-- Team scope: name, emails, events and enabled always change; url_sealed / secret_sealed only when
-- the caller gave a new URL (nullable sqlc.narg — NULL means "keep the current value").
UPDATE notification_channels SET name = sqlc.arg('name'), emails = sqlc.arg('emails'), events = sqlc.arg('events'),
    enabled = sqlc.arg('enabled'),
    url_sealed = coalesce(sqlc.narg('url_sealed'), url_sealed),
    secret_sealed = CASE WHEN sqlc.arg('clear_secret')::boolean THEN NULL ELSE coalesce(sqlc.narg('secret_sealed'), secret_sealed) END,
    updated_at = now()
WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id')
RETURNING *;

-- name: DeleteNotificationChannelInTeam :execrows
DELETE FROM notification_channels WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id');
